static inline void inet_csk_schedule_ack(struct sock *sk) /* <=== inet_csk_schedule_ack */ 
{
	inet_csk(sk)->icsk_ack.pending |= ICSK_ACK_SCHED;
}

static inline void tcp_ca_event(struct sock *sk, const enum tcp_ca_event event) /* <=== tcp_ca_event */ 
{
	const struct inet_connection_sock *icsk = inet_csk(sk);

	if (icsk->icsk_ca_ops->cwnd_event)
		icsk->icsk_ca_ops->cwnd_event(sk, event);
}

static inline void *current_text_addr(void) /* <=== current_text_addr */ 
{
	void *pc;

	asm volatile("mov $1f, %0; 1:":"=r" (pc));

	return pc;
}

static inline __u32 tcp_acceptable_seq(const struct sock *sk) /* <=== tcp_acceptable_seq */ 
{
	const struct tcp_sock *tp = tcp_sk(sk);

	if (!before(tcp_wnd_end(tp), tp->snd_nxt))
		return tp->snd_nxt;
	else
		return tcp_wnd_end(tp);
}

static inline void *current_text_addr(void) /* <=== current_text_addr */ 
{
	register void *pc asm("pc");
	return pc;
}

