static inline u32 prandom_u32_max(u32 ep_ro) /* <=== prandom_u32_max */ 
{
	return (u32)(((u64) prandom_u32() * ep_ro) >> 32);
}

static inline void tcp_skb_pcount_set(struct sk_buff *skb, int segs) /* <=== tcp_skb_pcount_set */ 
{
	TCP_SKB_CB(skb)->tcp_gso_segs = segs;
}

static inline struct tcphdr *tcp_hdr(const struct sk_buff *skb) /* <=== tcp_hdr */ 
{
	return (struct tcphdr *)skb_transport_header(skb);
}

bool tcp_oow_rate_limited(struct net *net, const struct sk_buff *skb, /* <=== tcp_oow_rate_limited */ 
			  int mib_idx, u32 *last_oow_ack_time)
{
	/* Data packets without SYNs are not likely part of an ACK loop. */
	if ((TCP_SKB_CB(skb)->seq != TCP_SKB_CB(skb)->end_seq) &&
	    !tcp_hdr(skb)->syn)
		goto not_rate_limited;

	if (*last_oow_ack_time) {
		s32 elapsed = (s32)(tcp_time_stamp - *last_oow_ack_time);

		if (0 <= elapsed && elapsed < sysctl_tcp_invalid_ratelimit) {
			NET_INC_STATS(net, mib_idx);
			return true;	/* rate-limited: don't send yet! */
		}
	}

	*last_oow_ack_time = tcp_time_stamp;

not_rate_limited:
	return false;	/* not rate-limited: go ahead, send dupack now! */
}

static void tcp_init_nondata_skb(struct sk_buff *skb, u32 seq, u8 flags) /* <=== tcp_init_nondata_skb */ 
{
	skb->ip_summed = CHECKSUM_PARTIAL;
	skb->csum = 0;

	TCP_SKB_CB(skb)->tcp_flags = flags;
	TCP_SKB_CB(skb)->sacked = 0;

	tcp_skb_pcount_set(skb, 1);

	TCP_SKB_CB(skb)->seq = seq;
	if (flags & (TCPHDR_SYN | TCPHDR_FIN))
		seq++;
	TCP_SKB_CB(skb)->end_seq = seq;
}

static inline bool before(__u32 seq1, __u32 seq2) /* <=== before */ 
{
        return (__s32)(seq1-seq2) < 0;
}

static inline struct inet_connection_sock *inet_csk(const struct sock *sk) /* <=== inet_csk */ 
{
	return (struct inet_connection_sock *)sk;
}

static inline void skb_set_tcp_pure_ack(struct sk_buff *skb) /* <=== skb_set_tcp_pure_ack */ 
{
	skb->truesize = 2;
}

static inline gfp_t sk_gfp_mask(const struct sock *sk, gfp_t gfp_mask) /* <=== sk_gfp_mask */ 
{
	return gfp_mask | (sk->sk_allocation & __GFP_MEMALLOC);
}

void tcp_send_ack(struct sock *sk) /* <=== tcp_send_ack */ 
{
	struct sk_buff *buff;

	/* If we have been reset, we may not send again. */
	if (sk->sk_state == TCP_CLOSE)
		return;

	tcp_ca_event(sk, CA_EVENT_NON_DELAYED_ACK);

	/* We are not putting this on the write queue, so
	 * tcp_transmit_skb() will set the ownership to this
	 * sock.
	 */
	buff = alloc_skb(MAX_TCP_HEADER,
			 sk_gfp_mask(sk, GFP_ATOMIC | __GFP_NOWARN));
	if (unlikely(!buff)) {
		inet_csk_schedule_ack(sk);
		inet_csk(sk)->icsk_ack.ato = TCP_ATO_MIN;
		inet_csk_reset_xmit_timer(sk, ICSK_TIME_DACK,
					  TCP_DELACK_MAX, TCP_RTO_MAX);
		return;
	}

	/* Reserve space for headers and prepare control bits. */
	skb_reserve(buff, MAX_TCP_HEADER);
	tcp_init_nondata_skb(buff, tcp_acceptable_seq(sk), TCPHDR_ACK);

	/* We do not want pure acks influencing TCP Small Queues or fq/pacing
	 * too much.
	 * SKB_TRUESIZE(max(1 .. 66, MAX_TCP_HEADER)) is unfortunately ~784
	 * We also avoid tcp_wfree() overhead (cache line miss accessing
	 * tp->tsq_flags) by using regular sock_wfree()
	 */
	skb_set_tcp_pure_ack(buff);

	/* Send it off, this clears delayed acks for us. */
	skb_mstamp_get(&buff->skb_mstamp);
	tcp_transmit_skb(sk, buff, 0, (__force gfp_t)0);
}

static inline struct tcp_sock *tcp_sk(const struct sock *sk) /* <=== tcp_sk */ 
{
	return (struct tcp_sock *)sk;
}

static inline u32 tcp_wnd_end(const struct tcp_sock *tp) /* <=== tcp_wnd_end */ 
{
	return tp->snd_una + tp->snd_wnd;
}

static inline void inet_csk_reset_xmit_timer(struct sock *sk, const int what, /* <=== inet_csk_reset_xmit_timer */ 
					     unsigned long when,
					     const unsigned long max_when)
{
	struct inet_connection_sock *icsk = inet_csk(sk);

	if (when > max_when) {
#ifdef INET_CSK_DEBUG
		pr_debug("reset_xmit_timer: sk=%p %d when=0x%lx, caller=%p\n",
			 sk, what, when, current_text_addr());
#endif
		when = max_when;
	}

	if (what == ICSK_TIME_RETRANS || what == ICSK_TIME_PROBE0 ||
	    what == ICSK_TIME_EARLY_RETRANS || what ==  ICSK_TIME_LOSS_PROBE) {
		icsk->icsk_pending = what;
		icsk->icsk_timeout = jiffies + when;
		sk_reset_timer(sk, &icsk->icsk_retransmit_timer, icsk->icsk_timeout);
	} else if (what == ICSK_TIME_DACK) {
		icsk->icsk_ack.pending |= ICSK_ACK_TIMER;
		icsk->icsk_ack.timeout = jiffies + when;
		sk_reset_timer(sk, &icsk->icsk_delack_timer, icsk->icsk_ack.timeout);
	}
#ifdef INET_CSK_DEBUG
	else {
		pr_debug("%s", inet_csk_timer_bug_msg);
	}
#endif
}

static inline void skb_mstamp_get(struct skb_mstamp *cl) /* <=== skb_mstamp_get */ 
{
	u64 val = local_clock();

	do_div(val, NSEC_PER_USEC);
	cl->stamp_us = (u32)val;
	cl->stamp_jiffies = (u32)jiffies;
}

